from itertools import product
from fractions import Fraction

values = [0, 1, 2, 3, -1, -2, -3]
scalars = [-1, 2, Fraction(1, 2)]
points = [list(p) for p in product(values, repeat=2)]

def vec(v):
    return "(" + ", ".join(str(x) for x in v) + ")"

def inside(words, p):
    x, y = p[0], p[1]
    if words[0] == "line":
        return int(words[1]) * x + int(words[2]) * y == int(words[3])
    if words[0] == "half":
        return int(words[1]) * x + int(words[2]) * y >= 0
    if words[0] == "quadrant":
        return x >= 0 and y >= 0
    if words[0] == "axes":
        return x * y == 0
    if words[0] == "parabola":
        return y == x ** 2
    if words[0] == "diagonals":
        return x ** 2 == y ** 2
    if words[0] == "zero":
        return x == 0 and y == 0
    return True

def subspace_test(words):
    members = [p for p in points if inside(words, p)]
    print(" ".join(words))
    passed = 0
    if inside(words, [0, 0]):
        print("  check 1: passes")
        passed = passed + 1
    else:
        print("  check 1: fails, (0, 0) is not in the set")
    bad = None
    for u in members:
        for v in members:
            s = [u[0] + v[0], u[1] + v[1]]
            if bad is None and not inside(words, s):
                bad = f"{vec(u)} + {vec(v)} = {vec(s)}"
    if bad is None:
        print("  check 2: passes")
        passed = passed + 1
    else:
        print(f"  check 2: fails, {bad}")
    bad = None
    for u in members:
        for c in scalars:
            s = [c * u[0], c * u[1]]
            if bad is None and not inside(words, s):
                bad = f"({c}){vec(u)} = {vec(s)}"
    if bad is None:
        print("  check 3: passes")
        passed = passed + 1
    else:
        print(f"  check 3: fails, {bad}")
    if passed == 3:
        print("  a subspace, as far as the grid shows")
    else:
        print("  not a subspace")

k = int(input())
for i in range(k):
    subspace_test(input().split())

