            p = p + 1
        if p == len(R):
            continue
        R[r], R[p] = R[p], R[r]
        k = R[r][c]
        R[r] = [x / k for x in R[r]]
        for i in range(len(R)):
            k = R[i][c]
            if i != r and k != 0:
                R[i] = [R[i][j] - k * R[r][j] for j in range(len(R[i]))]
        pivots.append(c)
    return R, pivots

def show(M):
    return "  ".join("[" + ", ".join(str(x) for x in row) + "]" for row in M)

def vec(v):
    return "(" + ", ".join(str(x) for x in v) + ")"

def times(A, x):
    return [sum(A[i][j] * x[j] for j in range(len(x))) for i in range(len(A))]

def read_matrix():
    m, n = [int(w) for w in input().split()]
    return [[Fraction(w) for w in input().split()] for i in range(m)]

def decide(A, b, R, pivots):
    n = len(A[0])
    for i in range(len(R)):
        if all(x == 0 for x in R[i][:n]) and R[i][n] != 0:
            print(f"  not in C(A): row {i + 1} says 0 = {R[i][n]}")
            return
    x = [Fraction(0)] * n
    for i in range(len(pivots)):
        x[pivots[i]] = R[i][n]
    print(f"  in C(A): x = {vec(x)}, A x = {vec(times(A, x))}")

